// and — the point of attack nine — never MIGRATE into it when a backend
// for their language lands.
const verifiable = inScopeRows.filter((r) => LSP_VERIFIABLE_LANGUAGES.has(r.lang)).reduce((a, r) => a + r.c, 0);
