s=s.replace("computeCoverage(rows, 50)","computeCoverage(rows, [{ lang: 'cpp', c: 50, inScope: true }])");
s=s.replace("computeCoverage([{ lang: 'cpp', c: 10, inScope: true }], 10)","computeCoverage([{ lang: 'cpp', c: 10, inScope: true }], [{ lang: 'cpp', c: 10, inScope: true }])");
