s=s.replace("    ], 10);\n\n    expect(r.unverifiable.map","    ], [{ lang: 'cpp', c: 10, inScope: true }]);\n\n    expect(r.unverifiable.map");
s=s.replace("computeCoverage([], 0).denominator","computeCoverage([], []).denominator");
s=s.replace("inScope: true }], 0);\n    expect(r.verifiable).toBe(0)","inScope: true }], []);\n    expect(r.verifiable).toBe(0)");
s=s.replace("  it('verifiability is scoped",`  it('★★ numerator is the same population as the denominator (949 over 19 printed 4995%)', () => {
    // Regression: health passed COUNT(*) of every LSP_VERIFIED edge — any relation, any
    // language, tracked or not — over verifiable in-scope CALLS only. Verified edges outside
    // that population (out-of-scope vendored C++, non-C++ edges) inflated the ratio past 100.
    const calls = [
      { lang: 'cpp', c: 19, inScope: true },
      { lang: 'cpp', c: 5000, inScope: false },
    ];
    const verifiedCalls = [
      { lang: 'cpp', c: 12, inScope: true },
      { lang: 'cpp', c: 930, inScope: false },
      { lang: 'python', c: 7, inScope: true },
    ];
    const r = computeCoverage(calls, verifiedCalls);

    expect(r.verified, 'only verifiable in-scope verified calls count').toBe(12);
    expect(r.pct).toBe(63);
  });

  it('verified can never exceed verifiable when numerator rows are a subset of the rows', () => {
    const rows = [{ lang: 'cpp', c: 19, inScope: true }];
    const r = computeCoverage(rows, rows);
    expect(r.pct).toBe(100);
  });

  it('verifiability is scoped`);
if(crlf) s=s.replace(/\n/g,'\r\n');
fs.writeFileSync(p,s);
E
